  // ==========================================================================
  // [1] 전역 상태 및 데이터베이스 관리 (IndexedDB)
  // ==========================================================================
  const DB_NAME = 'YewonESignDB';
  const DB_VERSION = 1;
  let db = null;

  // 2026학년도 체험교실 출근부 원본 1번~39번 공식 명단 및 정순서
  const OFFICIAL_SIGNERS_LIST = [
    '박은희', '예준호', '서민지', '양원자', '김미화', '김연옥', '서지언', '서호찬', '박진석', '김거울',
    '김형준', '이수연', '신유정', '유지혜', '박진우', '김동환', '박선옥', '정설희', '이선영', '정태욱',
    '김도형', '장재리', '임수정', '최준혁', '이경미', '김태현', '유경희', '탁은남', '예성원', '김경미',
    '박소영', '조유진', '김종찬', '하귀천', '장용수', '박상민', '김인진', '이장근', '이주성'
  ];
  const OFFICIAL_ORDER_MAP = new Map(OFFICIAL_SIGNERS_LIST.map((name, idx) => [name, idx]));

  // 공식 출근부 순서(1번~39번)로 서명 대상자를 정렬하는 헬퍼 함수
  function sortSignersInOfficialOrder(list) {
    if (!Array.isArray(list)) return [];
    const uniqueList = Array.from(new Set(list.filter(Boolean)));
    return uniqueList.sort((a, b) => {
      const orderA = OFFICIAL_ORDER_MAP.has(a) ? OFFICIAL_ORDER_MAP.get(a) : 999;
      const orderB = OFFICIAL_ORDER_MAP.has(b) ? OFFICIAL_ORDER_MAP.get(b) : 999;
      if (orderA !== orderB) {
        return orderA - orderB;
      }
      return a.localeCompare(b, 'ko');
    });
  }

  // 2026학년도 체험교실 출근부 원본 39명 출근부 PDF Base64 템플릿
  const ATTENDANCE_PDF_BASE64 = '';

  // 100% 복구된 실제 자필 서명 데이터 (Chrome LevelDB + 기제출 완료 PDF 합성 추출본)
